/// Average mass of each residue in a chain (free amino acid minus H2O), indexed by `aa_index`.
pub const RESIDUE_MASS_DA: [f64; 20] = [
    71.0788, 103.1388, 115.0886, 129.1155, 147.1766, 57.0519, 137.1411, 113.1594, 128.1741, 113.1594, 131.1926, 114.1038, 97.1167, 128.1307, 156.1875, 87.0782, 101.1051, 99.1326, 186.2132, 163.1760,
];

/// `ACDEFGHIKLMNPQRSTVWY` index of an amino-acid byte, or `None` for anything else.
pub fn aa_index(b: u8) -> Option<usize> {
    const ORDER: &[u8; 20] = b"ACDEFGHIKLMNPQRSTVWY";
    ORDER.iter().position(|&x| x == b.to_ascii_uppercase())
}

